        // Datetime needs to be in RFC3339 format
        OffsetDateTime startTime = OffsetDateTime.now();
        // Datetime needs to be in RFC3339 format
        OffsetDateTime endTime = OffsetDateTime.now();

        int samplingInterval = 1;

        Object statType = SOME_RAW_DATA;

        int page = 0;

